CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,full_name TEXT NOT NULL,email TEXT UNIQUE,role TEXT NOT NULL CHECK(role IN ('super_admin','admin','headteacher','bursar','teacher','parent','student')),password_hash TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT UNIQUE NOT NULL,expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS guardians(id BIGSERIAL PRIMARY KEY,full_name TEXT NOT NULL,email TEXT,phone TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS students(id BIGSERIAL PRIMARY KEY,first_name TEXT NOT NULL,last_name TEXT NOT NULL,admission_number TEXT UNIQUE NOT NULL,grade TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('pending','active','on_leave','suspended','graduated','transferred','withdrawn')),guardian_id BIGINT REFERENCES guardians(id),user_id BIGINT UNIQUE REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS staff(id BIGSERIAL PRIMARY KEY,user_id BIGINT UNIQUE REFERENCES users(id),staff_number TEXT UNIQUE NOT NULL,department TEXT,duty TEXT,subjects TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS applications(id BIGSERIAL PRIMARY KEY,reference TEXT UNIQUE NOT NULL,first_name TEXT NOT NULL,last_name TEXT NOT NULL,grade TEXT NOT NULL,guardian_name TEXT NOT NULL,guardian_email TEXT NOT NULL,guardian_phone TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','waitlisted')),student_id BIGINT REFERENCES students(id),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS reporting_checks(id BIGSERIAL PRIMARY KEY,application_id BIGINT UNIQUE REFERENCES applications(id),verified_by BIGINT REFERENCES users(id),documents_ok BOOLEAN NOT NULL DEFAULT false,materials_ok BOOLEAN NOT NULL DEFAULT false,notes TEXT,verified_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS content(id BIGSERIAL PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('news','gallery','slide','page')),title TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',image_url TEXT,category TEXT,year INTEGER,published BOOLEAN NOT NULL DEFAULT false,created_by BIGINT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS contact_messages(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,message TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS fee_charges(id BIGSERIAL PRIMARY KEY,student_id BIGINT NOT NULL REFERENCES students(id),academic_year INTEGER NOT NULL,term INTEGER NOT NULL CHECK(term BETWEEN 1 AND 3),item TEXT NOT NULL,amount NUMERIC(12,2) NOT NULL CHECK(amount>=0),UNIQUE(student_id,academic_year,term,item));
CREATE TABLE IF NOT EXISTS payments(id BIGSERIAL PRIMARY KEY,student_id BIGINT NOT NULL REFERENCES students(id),amount NUMERIC(12,2) NOT NULL CHECK(amount>0),method TEXT NOT NULL,reference TEXT UNIQUE NOT NULL,recorded_by BIGINT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS assignments(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,grade TEXT NOT NULL,description TEXT NOT NULL,deadline TIMESTAMPTZ,teacher_id BIGINT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS submissions(id BIGSERIAL PRIMARY KEY,assignment_id BIGINT REFERENCES assignments(id),student_id BIGINT REFERENCES students(id),answer TEXT,practice_mark NUMERIC(5,2),feedback TEXT,UNIQUE(assignment_id,student_id));
CREATE TABLE IF NOT EXISTS assessments(id BIGSERIAL PRIMARY KEY,student_id BIGINT NOT NULL REFERENCES students(id),subject TEXT NOT NULL,academic_year INTEGER NOT NULL,term INTEGER NOT NULL CHECK(term BETWEEN 1 AND 3),cat NUMERIC(5,2) CHECK(cat BETWEEN 0 AND 30),exam NUMERIC(5,2) CHECK(exam BETWEEN 0 AND 70),remark TEXT,approved BOOLEAN NOT NULL DEFAULT false,UNIQUE(student_id,subject,academic_year,term));
CREATE TABLE IF NOT EXISTS attendance(id BIGSERIAL PRIMARY KEY,student_id BIGINT REFERENCES students(id),day DATE NOT NULL,status TEXT NOT NULL CHECK(status IN ('present','absent','late','excused')),recorded_by BIGINT REFERENCES users(id),UNIQUE(student_id,day));
CREATE TABLE IF NOT EXISTS email_outbox(id BIGSERIAL PRIMARY KEY,recipient TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id BIGSERIAL PRIMARY KEY,actor_id BIGINT REFERENCES users(id),action TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT,details JSONB,created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_students_grade ON students(grade);CREATE INDEX IF NOT EXISTS idx_applications_status ON applications(status);CREATE INDEX IF NOT EXISTS idx_content_public ON content(kind,published,created_at);CREATE INDEX IF NOT EXISTS idx_sessions_expiry ON sessions(expires_at);
